type range = { lo : int; hi : int }

let int_min = -2147483648
let int_max = 2147483647
let full = { lo = int_min; hi = int_max }

(* [a.lo, a.hi] + [b.lo, b.hi]. If either end could leave the i32 range, the sum may wrap: return full. *)
let add_range (a : range) (b : range) : range =
  full

(* Same for multiplication. Watch the signs: the extremes can come from any pair of ends. *)
let mul_range (a : range) (b : range) : range =
  full
